solution.python:
def change(amount, coins):
    dp = [1] + [0] * amount
    for c in coins:
        for a in range(c, amount + 1): dp[a] += dp[a - c]
    return dp[amount]

solution.cpp:
long long change(int amount, vector<int>& coins) {
    vector<long long> dp(amount + 1, 0); dp[0] = 1;
    for (int c : coins) for (int a = c; a <= amount; a++) dp[a] += dp[a - c];
    return dp[amount];
}
